#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Embed a MicroPixel App Bundle (.mpxbundle) as a C array header.

Usage:  python tools/mpx/bundle_to_header.py <bundle> <out-header>
"""
import sys

def main():
    if len(sys.argv) != 3:
        raise SystemExit("usage: bundle_to_header.py <bundle> <out-header>")
    data = open(sys.argv[1], "rb").read()
    lines = [
        "/* Auto-generated by tools/mpx/bundle_to_header.py - do not edit. */",
        "#ifndef _MPX_APP_WASM_BUNDLE_H_",
        "#define _MPX_APP_WASM_BUNDLE_H_",
        "",
        "static const unsigned char k_mpx_app_bundle[] = {",
    ]
    hexvals = ["0x%02x" % b for b in data]
    for i in range(0, len(hexvals), 12):
        lines.append("    " + ", ".join(hexvals[i:i + 12]) + ",")
    lines += [
        "};",
        "#define MPX_APP_BUNDLE_SIZE (sizeof(k_mpx_app_bundle))",
        "",
        "#endif /* _MPX_APP_WASM_BUNDLE_H_ */",
    ]
    with open(sys.argv[2], "w") as f:
        f.write("\n".join(lines) + "\n")
    print("wrote", sys.argv[2], len(data), "bytes")

if __name__ == "__main__":
    main()
